<script setup>
import {useForm,Link} from '@inertiajs/vue3';import AppLayout from '../../Layouts/AppLayout.vue';const form=useForm({customer_name:'',phone:'',address:'',payment_method:'transfer'});const submit=()=>form.post('/checkout');
</script>
<template><AppLayout><div class="page" style="max-width:760px;margin:auto"><h1 class="page-title">Checkout</h1><div class="panel"><form @submit.prevent="submit"><div class="field"><label>Nama penerima</label><input v-model="form.customer_name" required><small style="color:#dc3545">{{form.errors.customer_name}}</small></div><div class="field"><label>Nomor telepon</label><input v-model="form.phone" required><small style="color:#dc3545">{{form.errors.phone}}</small></div><div class="field"><label>Alamat lengkap</label><textarea v-model="form.address" rows="4" required></textarea><small style="color:#dc3545">{{form.errors.address}}</small></div><div class="field"><label>Metode pembayaran</label><select v-model="form.payment_method"><option value="transfer">Transfer bank (simulasi)</option><option value="cod">Bayar di tempat (COD)</option></select></div><p class="muted">Catatan: pembayaran pada starter ini masih berupa simulasi, belum terhubung ke payment gateway.</p><button class="btn" :disabled="form.processing">Buat Pesanan</button> <Link href="/keranjang" class="btn light">Kembali</Link></form></div></div></AppLayout></template>
